'use strict';
const STORAGE_KEY = 'studio-navigation-prototype-v1';
const initialState = () => ({ filters:{role:'all',search:'',scenario:'all',page:1}, drafts:{}, created:{}, materialUsed:false, materialRefs:{}, issuesReviewed:false, delivery:false, productReviewed:false, productDelivery:false, preference:null, roleName:'AI科技博主', roleAudience:'想理解科技变化、重视实际用途的普通读者', rolePosition:'用真实案例解释新技术，明确区分事实与判断。', sourceSelection:{}, roleDraft:null, materialDrafts:{}, scopeDraft:null });
let state;
try { state = {...initialState(), ...JSON.parse(sessionStorage.getItem(STORAGE_KEY) || 'null')}; } catch { state = initialState(); }
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function persist(){ try {sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));} catch {toast('浏览器未允许会话保存；当前草稿仅在本次打开时保留。');} }
const link = (route,label,primary=false) => `<a class="button${primary?' primary':''}" href="#/${route}">${esc(label)} <span aria-hidden="true">→</span></a>`;
const textLink = (route,label) => `<a class="text-link" href="#/${route}">${esc(label)} →</a>`;
const badge = (text,type='') => `<span class="badge ${type}">${esc(text)}</span>`;
const fact = (name,value) => `<div class="fact-line"><span>${esc(name)}</span><span>${esc(value)}</span></div>`;
const notice = (text,green=false) => `<div class="notice${green?' green':''}">${esc(text)}</div>`;
const panels = (items,three=false) => `<div class="grid${three?' three':''}">${items.join('')}</div>`;
const card = (route,title,description,tag='',symbol='◈',color='') => `<a class="card" href="#/${route}"><div class="thumb ${color}" aria-hidden="true">${symbol}</div><div class="card-body">${tag}<h3>${esc(title)}</h3><p>${esc(description)}</p></div><span class="chevron" aria-hidden="true">›</span></a>`;
const crumbs = items => `<div class="breadcrumb"><a href="#/home">工作空间</a>${items.map(([label,route])=>`<span aria-hidden="true">/</span>${route?`<a href="#/${route}">${esc(label)}</a>`:`<span>${esc(label)}</span>`}`).join('')}</div>`;
const heading = (title,description,action='',eyebrow='') => `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`;
const section = (title,body,aside='') => `<section class="section"><div class="section-head"><h2>${esc(title)}</h2>${aside}</div>${body}</section>`;
const empty = (title,description,action='') => `<div class="empty"><div class="empty-icon" aria-hidden="true">◌</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${action}</div>`;
const tabs = (items,current) => `<nav class="tabs" aria-label="当前资料分类">${items.map(([label,route])=>`<a href="#/${route}" ${route===current?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>`;
const steps = (labels,current) => `<ol class="steps" aria-label="任务步骤">${labels.map((label,i)=>`<li class="${i===current?'active':''}" ${i===current?'aria-current="step"':''}>${esc(label)}</li>`).join('')}</ol>`;
const navGroups = [
 ['日常工作',[['home','今日工作','⌂'],['opportunities','内容机会','◈'],['persona','角色创作','◉'],['product','商品视频','▣'],['review','审阅与交付','☑']]],
 ['长期资料',[['projects','项目档案','▤'],['identities','角色与账号','♧'],['library','素材与知识','▧'],['learning','效果复盘','↗']]],
 ['工作空间',[['settings','系统设置','⚙']]]
];
